//! Static data tables for the UASTC HDR 6x6 decoder: the 75 block-mode
//! descriptors a coded block selects among, the reuse-encoding position
//! deltas, and the dense index-to-seed maps for 2- and 3-partition blocks.

/// One row per coded block mode. ISE ranges are the standard 0..=20 indices;
/// `flags` is the encoder-side level mask (kept for fidelity, unused by the
/// decoder); `dp_channel` is the dual-plane color component selector.
#[derive(Clone, Copy)]
pub struct BlockModeDesc {
    pub dp: bool,
    pub cem: u32,
    pub num_partitions: u32,
    pub grid_x: u32,
    pub grid_y: u32,
    pub endpoint_ise_range: u32,
    pub weight_ise_range: u32,
    pub transcode_endpoint_ise_range: u32,
    pub transcode_weight_ise_range: u32,
    #[allow(dead_code)]
    pub flags: u32,
    pub dp_channel: u32,
}

